begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('f1040000-0000-0000-0000-000000000001','identity-owner@test.invalid'),('f1040000-0000-0000-0000-000000000002','identity-staff@test.invalid');
insert into public.tenants(id,name,slug)values('f1041000-0000-0000-0000-000000000001','Identity QA','identity-qa'),('f1041000-0000-0000-0000-000000000002','Identity Other','identity-other');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f1041000-0000-0000-0000-000000000001','f1040000-0000-0000-0000-000000000001','owner'),('f1041000-0000-0000-0000-000000000001','f1040000-0000-0000-0000-000000000002','member');
insert into public.properties(id,tenant_id,name,property_type)values('f1042000-0000-0000-0000-000000000001','f1041000-0000-0000-0000-000000000001','Identity Hotel','hotel'),('f1042000-0000-0000-0000-000000000002','f1041000-0000-0000-0000-000000000001','Second Hotel','hotel'),('f1042000-0000-0000-0000-000000000003','f1041000-0000-0000-0000-000000000002','Other Hotel','hotel');
select 'f1042000-0000-0000-0000-000000000001'::uuid as pid,'f1041000-0000-0000-0000-000000000001'::uuid as tenant,'f1043000-0000-0000-0000-000000000001'::uuid as gid,'f1044000-0000-0000-0000-000000000001'::uuid as rid,'f1046000-0000-0000-0000-000000000001'::uuid as cid \gset
insert into public.property_memberships(tenant_id,property_id,user_id)values(:'tenant',:'pid','f1040000-0000-0000-0000-000000000002');
insert into public.guests(id,tenant_id,full_name,phone)values(:'gid',:'tenant','Old Test Guest','+15550001040'),('f1043000-0000-0000-0000-000000000002',:'tenant','Unused Test Guest',null),('f1043000-0000-0000-0000-000000000003',:'tenant','New Correct Guest','+15550001040'),('f1043000-0000-0000-0000-000000000004','f1041000-0000-0000-0000-000000000002','Other Guest',null);
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)values(:'rid',:'tenant',:'pid',:'gid','confirmed',current_date,current_date+1,100,'INR');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f1045000-0000-0000-0000-000000000001',:'tenant',:'pid','99104001','99104002','qa-no-token'),('f1045000-0000-0000-0000-000000000002',:'tenant','f1042000-0000-0000-0000-000000000002','99104003','99104004','qa-no-token');
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,guest_id,last_inbound_at)values(:'cid',:'tenant',:'pid','f1045000-0000-0000-0000-000000000001','15550001040',:'gid',now()),('f1046000-0000-0000-0000-000000000002',:'tenant','f1042000-0000-0000-0000-000000000002','f1045000-0000-0000-0000-000000000002','15550001040',:'gid',now());
insert into public.whatsapp_guest_authorizations(property_id,tenant_id,guest_id,wa_contact_id,conversation_id,status,evidence)values(:'pid',:'tenant',:'gid','15550001040',:'cid','granted','Synthetic test'),('f1042000-0000-0000-0000-000000000002',:'tenant',:'gid','15550001040','f1046000-0000-0000-0000-000000000002','granted','Other hotel permission');
insert into public.guest_access_tokens(tenant_id,property_id,reservation_id,token_hash,expires_at)values(:'tenant',:'pid',:'rid','identity-reset-test-hash',now()+interval '1 day');
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status)values('f1047000-0000-0000-0000-000000000001',:'tenant',:'pid',:'cid','out','text','Old guest private details','queued');
insert into private.whatsapp_booking_contacts(reservation_id,property_id,guest_id,conversation_id,phone,evidence,actor_id)values(:'rid',:'pid',:'gid',:'cid','15550001040','Synthetic prior permission','f1040000-0000-0000-0000-000000000001');
insert into public.whatsapp_marketing_permissions(property_id,tenant_id,wa_contact_id,status,evidence,actor_id)values(:'pid',:'tenant','15550001040','granted','Synthetic marketing permission','f1040000-0000-0000-0000-000000000001');
insert into public.consent_records(property_id,tenant_id,wa_contact_id,status,source)values(:'pid',:'tenant','15550001040','opted_out','whatsapp_keyword');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((public.guest_identity_workspace(:'pid')->>'total')::integer,3,'owner sees this hotel profiles plus unused tenant profiles');
select is((public.guest_identity_workspace(:'pid','old test')->>'total')::integer,1,'search selects the old guest');
select throws_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001040'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'22023','Resolve this guest’s confirmed or in-house stays before resetting the WhatsApp link.','active bookings block reset');
select throws_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001041'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'40001',null,'stale phone is rejected');
select throws_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001040'',''Wrong name'',''Incorrect old identity link'')',:'pid',:'gid'),'22023',null,'confirmation must match the guest');
select throws_ok(format('select public.manage_guest_identity(%L,%L,''delete'',''+15550001040'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'22023',null,'history cannot be deleted');
select throws_ok($$select public.guest_identity_workspace('f1042000-0000-0000-0000-000000000003')$$,'42501',null,'another tenant cannot be searched');
select throws_ok(format('select public.manage_guest_identity(%L,''f1043000-0000-0000-0000-000000000004'',''delete'','''',''Other Guest'',''Remove unused profile'')',:'pid'),'42501',null,'another tenant guest cannot be deleted');
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok(format('select public.guest_identity_workspace(%L)',:'pid'),'42501',null,'ordinary member cannot manage profiles');
select throws_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001040'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'42501',null,'ordinary member cannot reset a binding');
reset role;
update public.reservations set status='cancelled'where id=:'rid';
update public.messages set status='sending'where id='f1047000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001040'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'22023','A message is sending or its delivery is uncertain. Resolve its delivery status before resetting.','in-flight delivery blocks reset');
reset role;
update public.messages set status='queued'where id='f1047000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok(format('select public.manage_guest_identity(%L,%L,''reset'',''+15550001040'',''Old Test Guest'',''Incorrect old identity link'')',:'pid',:'gid'),'reset succeeds after resolving the booking');
reset role;
select is((select guest_id from public.conversations where id=:'cid'),null::uuid,'conversation is unlinked');
select is((select last_inbound_at from public.conversations where id=:'cid'),null::timestamptz,'old free-text window does not transfer');
select is((select count(*)from public.whatsapp_guest_authorizations where property_id=:'pid'and guest_id=:'gid'),0::bigint,'old authorization no longer reserves the number');
select is((select count(*)from private.whatsapp_booking_contacts where property_id=:'pid'and guest_id=:'gid'),0::bigint,'prior welcome permission is removed');
select ok((select revoked_at is not null from public.guest_access_tokens where reservation_id=:'rid'),'old private links are revoked');
select is((select status from public.messages where id='f1047000-0000-0000-0000-000000000001'),'failed','queued old private message is cancelled');
select ok((select guest_identity_reset_at is not null from public.messages where id='f1047000-0000-0000-0000-000000000001'),'old message cannot silently become valid after relinking');
select throws_ok($$update public.messages set status='queued'where id='f1047000-0000-0000-0000-000000000001'$$,'22023',null,'even a direct retry of the old message is rejected');
select ok(private.inbox_delivery_error('f1047000-0000-0000-0000-000000000001')like '%reset%','delivery checks reject the old message');
select is((select status from public.whatsapp_marketing_permissions where property_id=:'pid'order by recorded_at desc,id desc limit 1),'revoked','marketing permission is revoked');
select ok(private.is_opted_out(:'pid','15550001040'),'STOP is preserved');
select ok(exists(select 1 from public.reservations where id=:'rid'),'reservation history is preserved');
select ok(exists(select 1 from public.guests where id=:'gid'),'guest profile is preserved');
select is((select guest_id from public.conversations where id='f1046000-0000-0000-0000-000000000002'),:'gid'::uuid,'other hotel binding is untouched');
select is((select status from public.whatsapp_guest_authorizations where property_id='f1042000-0000-0000-0000-000000000002'and guest_id=:'gid'),'granted','other hotel permission is untouched');
select is((select count(*)from private.guest_identity_audit where guest_id=:'gid'and action='reset_whatsapp_link'),1::bigint,'reset is audited');
-- Rebinding is possible only with a new permission record; STOP still has to be respected.
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)values('f1044000-0000-0000-0000-000000000002',:'tenant',:'pid','f1043000-0000-0000-0000-000000000003','confirmed',current_date+2,current_date+3,100,'INR');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok(format('select public.record_whatsapp_booking_contact(%L,''f1044000-0000-0000-0000-000000000002'',''New verified booking permission'',true)',:'pid'),'22023','Guest has stopped messages. They must contact the hotel to resume.','reset never bypasses STOP for a successor');
reset role;
-- Fixture simulates a later guest-initiated resume; production reset never edits this record.
delete from public.consent_records where property_id=:'pid'and wa_contact_id='15550001040';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok(format('select public.record_whatsapp_booking_contact(%L,''f1044000-0000-0000-0000-000000000002'',''New verified booking permission'',true)',:'pid'),'correct guest can bind with fresh permission after reset');
select lives_ok(format('select public.manage_guest_identity(%L,''f1043000-0000-0000-0000-000000000002'',''delete'','''',''Unused Test Guest'',''Remove unused test profile'')',:'pid'),'owner deletes a genuinely unused profile');
reset role;
select ok(not exists(select 1 from public.guests where id='f1043000-0000-0000-0000-000000000002'),'unused profile is removed');
select is((select count(*)from private.guest_identity_audit where action='deleted_unused_profile'and property_id=:'pid'),1::bigint,'unused deletion is audited');
-- A conversation-only profile still has history after its number is released.
insert into public.guests(id,tenant_id,full_name,phone)values('f1043000-0000-0000-0000-000000000005',:'tenant','Chat Only Guest','+15550001045');
insert into public.conversations(tenant_id,property_id,connection_id,wa_contact_id,guest_id)values(:'tenant',:'pid','f1045000-0000-0000-0000-000000000001','15550001045','f1043000-0000-0000-0000-000000000005');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1040000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.manage_guest_identity(:'pid','f1043000-0000-0000-0000-000000000005','reset','+15550001045','Chat Only Guest','Correct old conversation-only identity');
reset role;
select ok(not private.guest_profile_unused('f1043000-0000-0000-0000-000000000005'),'resetting a conversation-only profile does not erase its history classification');
set local role anon;
select throws_ok(format('select public.guest_identity_workspace(%L)',:'pid'),'42501',null,'anonymous callers cannot read the directory');
select *from finish();
rollback;
